// ── HELPERS ───────────────────────────────────────────────
// Salva uid localmente (não precisa sincronizar entre as duas)
function useLS(key, init) {
  const [val, setVal] = useState(() => {
    try { const s = localStorage.getItem(key); return s ? JSON.parse(s) : init; }
    catch { return init; }
  });
  useEffect(() => { try { localStorage.setItem(key, JSON.stringify(val)); } catch {} }, [key, val]);
  return [val, setVal];
}

// Sincroniza dados compartilhados com Firebase em tempo real
function deepMerge(base, override) {
  const result = { ...base };
  for (const key of Object.keys(override || {})) {
    if (
      override[key] !== null &&
      typeof override[key] === "object" &&
      !Array.isArray(override[key]) &&
      typeof base[key] === "object" &&
      !Array.isArray(base[key])
    ) {
      result[key] = deepMerge(base[key], override[key]);
    } else if (override[key] !== undefined) {
      result[key] = override[key];
    }
  }
  return result;
}

function useFirebase(key, init) {
  const [val, setValLocal] = useState(init);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    const r = dbRef(db, key);
    const unsub = onValue(r, (snap) => {
      if (snap.exists()) {
        // Merge com INIT para garantir que campos novos existam
        setValLocal(deepMerge(init, snap.val()));
      } else {
        set(r, init);
        setValLocal(init);
      }
      setLoaded(true);
    });
    return () => unsub();
  }, [key]);

  const setVal = (updater) => {
    setValLocal(prev => {
      const next = typeof updater === "function" ? updater(prev) : updater;
      set(dbRef(db, key), next);
      return next;
    });
  };

  return [val, setVal, loaded];
}

function fmtDate(d) {
  if (!d) return "";
  return new Date(d + "T12:00:00").toLocaleDateString("pt-BR", { day:"2-digit", month:"short" });
}

function timeAgo(ts) {
  const diff = Date.now() - ts;
  if (diff < 60000) return "agora";
  if (diff < 3600000) return `${Math.floor(diff/60000)}min atrás`;
  if (diff < 86400000) return `${Math.floor(diff/3600000)}h atrás`;
  return `${Math.floor(diff/86400000)}d atrás`;
}

